import{_ as u,a0 as o,w as p,s as l,ao as r,I as s,x as e,a1 as a,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const U=JSON.parse('{"title":"每日Ubuntu小技巧 - 使用舊式Gnome風格的菜單 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧 - 使用舊式Gnome風格的菜單 | LCTT (201312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧 - 使用舊式Gnome風格的菜單 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧 - 使用舊式Gnome風格的菜單 | LCTT (201312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201312/Daily Ubuntu Tips–Like GNOME Classic Menu？ Get Classic Menu Indicator","title":"每日Ubuntu小技巧 - 使用舊式Gnome風格的菜單","tag":"201312","desc":""},"relativePath":"201312/Daily Ubuntu Tips–Like GNOME Classic Menu？ Get Classic Menu Indicator.md","filePath":"[post].md"}'),d={name:"201312/Daily Ubuntu Tips–Like GNOME Classic Menu？ Get Classic Menu Indicator.md"};function m(b,t,c,C,T,M){const n=o("Link");return p(),l("div",null,[t[11]||(t[11]=r(`<h1 id="每日ubuntu小技巧-使用舊式gnome風格的菜單" tabindex="-1">每日Ubuntu小技巧 - 使用舊式Gnome風格的菜單 <a class="header-anchor" href="#每日ubuntu小技巧-使用舊式gnome風格的菜單" aria-label="Permalink to “每日Ubuntu小技巧 - 使用舊式Gnome風格的菜單”">​</a></h1><p>喜歡GNOME風格菜單？安裝Class Menu Indicator吧。</p><p>對於那些從開始就一直關注Ubuntu操作系統的人，他們看見幾乎所有的Ubuntu經歷的改變。發生了許多的改變，尤其是在桌面部分。從經典的GNOME桌面環境到Unity，Ubuntu已經完全地重新設計了。</p><p>對於那些新用户，他們所知道的就是Unity桌面環境，僅僅只是聽説過或者見過之前Ubuntu的原始GNOME桌面環境。</p><p>如果你是一個老資格用户，想要在Ubuntu的Unity回到GNOME風格的菜單，安裝Classic Menu Indicator 可以解決這個問題。這個有趣的包被安裝在頂部面板的通知區域，在Ubuntu中帶回了GNOME風格菜單體驗。</p><p>像經典的GNOME菜單一樣，它包括所有的應用和經典菜單結構。對於曾經使用過它的人們是容易導航和開啓應用。對於新用户，它也是容易掌握。</p><p>接下來的簡短指導將會告訴你如何在Ubuntu中安裝這個包。</p><p>馬上開始，在鍵盤上按下 <strong>Ctrl – Alt – T</strong> 打開終端。</p><p>打開完畢後，運行下列命令，加入它的PPA文件</p><pre><code>sudo apt-add-repository ppa:diesch/testing
</code></pre><p>接來下，運行下列命令安裝它。</p><pre><code>sudo apt-get update &amp;&amp; sudo apt-get install classicmenu-indicator
</code></pre><p>安裝完成後，在Unity Dash中啓動。它叫Classic Menu Indicator。當你啓動它的時候，它會自動的嵌入頂部面板，如下圖。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/11/classic-menu-indicator.png" alt=""></p><h2 id="就是這樣-使用並享受吧" tabindex="-1">就是這樣，使用並享受吧！ <a class="header-anchor" href="#就是這樣-使用並享受吧" aria-label="Permalink to “就是這樣，使用並享受吧！”">​</a></h2>`,15)),s("p",null,[t[1]||(t[1]=e("via: ",-1)),a(n,{href:"http://www.liberiangeek.net/2013/11/daily-ubuntu-tipslike-gnome-classic-menu-get-classic-menu-indicator/"},{default:i(()=>[...t[0]||(t[0]=[e("http://www.liberiangeek.net/2013/11/daily-ubuntu-tipslike-gnome-classic-menu-get-classic-menu-indicator/",-1)])]),_:1})]),s("p",null,[t[4]||(t[4]=e("譯者：",-1)),a(n,{href:"http://blog.csdn.net/Vic___"},{default:i(()=>[...t[2]||(t[2]=[e("Vic___",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),a(n,{href:"https://github.com/wxy"},{default:i(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[8]||(t[8]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),a(n,{href:"http://linux.cn/"},{default:i(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const f=u(d,[["render",m]]);export{U as __pageData,f as default};
